using System.Text.Json.Nodes;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media.Imaging;
namespace ArchiveReader;
public partial class FactReviewWindow:Window
{
 readonly string record;readonly Func<string,JsonObject?,CancellationToken,Task<JsonNode>> worker;JsonObject? snapshot;JsonArray? factRect;string? imagePath;bool busy,loading;
 public string? SelectedPageId{get;private set;}public string? SelectedRecordId{get;private set;}
 static string T(string s)=>Localizer.Text(s);
 Task<JsonNode> Call(string command,JsonObject args)=>worker(command,args,default);
 public FactReviewWindow(string page,string record,Func<string,JsonObject?,CancellationToken,Task<JsonNode>> worker){this.record=record;this.worker=worker;InitializeComponent();Loaded+=async(_,_)=>{Localizer.Apply(this,Localizer.Language);await Run(async()=>{await Reload();var rendered=await Call("render",new(){["id"]=page,["whole"]=true});imagePath=rendered["path"]!.ToString();Preview();if(Environment.GetCommandLineArgs().Contains("--smoke-facts")){await LoadNeighbors();Tabs.IsEnabled=true;for(int i=0;i<Tabs.Items.Count;i++){Tabs.SelectedIndex=i;SmokeCapture.Save(this,"facts-ui",$"tab-{i}.png");}Tabs.SelectedIndex=0;Fields.SelectedItem=Fields.Items.Cast<GenealogyRow>().First(r=>r.Data["field"]?.ToString()=="kinship");await ShowField();SmokeCapture.Save(this,"facts-ui","kinship.png");Close();}});};}
 async Task Run(Func<Task> action){if(busy)return;busy=true;Tabs.IsEnabled=false;try{await action();}catch(Exception ex){Status.Text=T(ex.Message);}finally{busy=false;Tabs.IsEnabled=true;}}
 static string FieldLabel(string key)=>key=="kinship"?T("Спорідненість"):ExtractionWindow.Field(key);
 static string State(string? state)=>T(state switch{"document_observation"=>"Спостереження в документі","transcription"=>"Прочитання тексту","hypothesis"=>"Гіпотеза","corroborated"=>"Підтверджено незалежними джерелами",_=>""});
 string? Field=>(Fields.SelectedItem as GenealogyRow)?.Data["field"]?.ToString();
 async Task Reload(){var selected=Field;snapshot=(await Call("fact_reviews",new(){["record"]=record})).AsObject();loading=true;Fields.ItemsSource=snapshot["facts"]!.AsArray().Select(n=>new GenealogyRow(n!.AsObject(),FieldLabel(n["field"]!.ToString())+(n["stale"]?.GetValue<bool>()==true?" · "+T("Доказ змінився"):""))).ToList();Fields.SelectedItem=Fields.Items.Cast<GenealogyRow>().FirstOrDefault(r=>r.Data["field"]?.ToString()==selected)??Fields.Items.Cast<GenealogyRow>().First();loading=false;await ShowField();}
 async void SelectField(object sender,SelectionChangedEventArgs e){if(!loading)await Run(ShowField);}
 async Task ShowField(){if(Fields.SelectedItem is not GenealogyRow row)return;var saved=row.Data["assessment"];factRect=saved?["source"]?["rect"]?.DeepClone().AsArray();Preview();Value.Text=saved?["value"]?.ToString()??row.Data["value"]?.ToString()??"";Note.Text=saved?["note"]?.ToString()??"";FactState.SelectedItem=FactState.Items.Cast<ComboBoxItem>().FirstOrDefault(i=>i.Tag.ToString()==saved?["status"]?.ToString())??FactState.Items[0];Reviewed.IsChecked=false;Citation.Text=snapshot?["source"]?["citation"]?.ToString();var history=await Call("fact_history",new(){["record"]=record,["field"]=Field});History.Text=string.Join("\n\n",history.AsArray().Select(h=>h?["created"]+" · "+State(h?["after"]?["status"]?.ToString())+"\n"+h?["after"]?["value"]+"\n"+h?["after"]?["note"]));await LoadSupports();}
 async Task LoadSupports(){Supports.ItemsSource=(await Call("fact_supports",new(){["record"]=record,["query"]=Query.Text})).AsArray().Select(n=>new GenealogyRow(n!.AsObject(),n["values"]?["person"]+" · "+n["values"]?["date"]+" · "+n["citation"])).ToList();var saved=(Fields.SelectedItem as GenealogyRow)?.Data["assessment"]?["supports"] as JsonArray;if(saved!=null){var all=Supports.Items.Cast<GenealogyRow>().ToList();foreach(var item in saved)if(item is JsonObject proof&&!all.Any(r=>r.Data["record"]?.ToString()==proof["record"]?.ToString()))all.Insert(0,new GenealogyRow(proof,proof["values"]?["person"]+" · "+proof["citation"]));Supports.ItemsSource=all;}foreach(var row in Supports.Items.Cast<GenealogyRow>())if(saved?.Any(s=>s?["record"]?.ToString()==row.Data["record"]?.ToString())==true)Supports.SelectedItems.Add(row);}
 void Preview(){if(imagePath==null)return;var image=new BitmapImage();image.BeginInit();image.CacheOption=BitmapCacheOption.OnLoad;image.UriSource=new Uri(imagePath);image.EndInit();image.Freeze();if(factRect is JsonArray r){int x=(int)(r[0]!.GetValue<double>()*image.PixelWidth),y=(int)(r[1]!.GetValue<double>()*image.PixelHeight);int w=Math.Min(image.PixelWidth-x,Math.Max(1,(int)(r[2]!.GetValue<double>()*image.PixelWidth))),h=Math.Min(image.PixelHeight-y,Math.Max(1,(int)(r[3]!.GetValue<double>()*image.PixelHeight)));Scan.Source=new CroppedBitmap(image,new Int32Rect(x,y,w,h));}else Scan.Source=image;}
 void PickEvidence(object sender,RoutedEventArgs e){if(imagePath==null)return;var picker=new RegionPicker(imagePath){Owner=this};if(picker.ShowDialog()==true){factRect=picker.Bounds;Preview();}}
 async void FindSupports(object sender,RoutedEventArgs e)=>await Run(LoadSupports);
 async void SaveFact(object sender,RoutedEventArgs e)=>await Run(async()=>{if(Field==null||snapshot==null)return;var saved=(Fields.SelectedItem as GenealogyRow)?.Data["assessment"];var supports=new JsonArray(Supports.SelectedItems.Cast<GenealogyRow>().Select(r=>new JsonObject{["record"]=r.Data["record"]!.ToString(),["signature"]=r.Data["signature"]!.ToString()}).ToArray());await Call("fact_save",new(){["record"]=record,["field"]=Field,["value"]=Value.Text,["status"]=((ComboBoxItem)FactState.SelectedItem).Tag.ToString(),["note"]=Note.Text,["signature"]=snapshot["source"]!["signature"]!.ToString(),["revision"]=saved?["revision"]?.ToString(),["rect"]=factRect?.DeepClone(),["supports"]=supports,["reviewed"]=Reviewed.IsChecked==true});await Reload();Status.Text=T("Збережено");});
 async void FindNeighbors(object sender,RoutedEventArgs e)=>await Run(LoadNeighbors);
 async Task LoadNeighbors(){Neighbors.ItemsSource=(await Call("neighbor_candidates",new(){["record"]=record})).AsArray().Select(n=>new GenealogyRow(n!.AsObject(),n["source"]?["values"]?["person"]+" · "+n["source"]?["number"]+" · "+n["score"])).ToList();Neighbors.SelectedIndex=0;}
 void SelectNeighbor(object sender,SelectionChangedEventArgs e){if(Neighbors.SelectedItem is not GenealogyRow row)return;var n=row.Data;NeighborEvidence.Text=n["source"]?["citation"]+"\n"+T("Збіги")+": "+string.Join(", ",n["signals"]!.AsArray().Select(s=>FieldLabel(s!["field"]!.ToString())))+"\n"+T("Відмінності")+": "+string.Join("; ",n["differences"]!.AsArray().Select(s=>FieldLabel(s!["field"]!.ToString())+": "+s["left"]+" / "+s["right"]))+"\n"+n["source"]?["values"]?["text"];}
 void OpenNeighbor(object sender,RoutedEventArgs e){if(Neighbors.SelectedItem is GenealogyRow row){SelectedPageId=row.Data["source"]!["page"]!.ToString();SelectedRecordId=row.Data["source"]!["record"]!.ToString();DialogResult=true;}}
}
